ALTER TABLE branches ADD COLUMN email_address VARCHAR(255);

ON CONFLICT (code) DO UPDATE SET
name=EXCLUDED.name, phone_number=EXCLUDED.phone_number, whatsapp_number=EXCLUDED.whatsapp_number,
email_address=EXCLUDED.email_address, collection_enabled=TRUE, active=TRUE, updated_at=now();

UPDATE branches SET active=FALSE, updated_at=now() WHERE code='DEMO-HRE';

SELECT branch.id, demo.product_id, demo.amount, demo.currency
FROM branches branch
CROSS JOIN branch_prices demo
WHERE branch.id::text LIKE '11000000-%'
  AND demo.branch_id='10000000-0000-0000-0000-000000000001'
  AND demo.effective_to IS NULL
ON CONFLICT (branch_id, product_id) WHERE effective_to IS NULL
DO UPDATE SET amount=EXCLUDED.amount, currency=EXCLUDED.currency;

SELECT branch.id, demo.product_id, demo.on_hand, 0, demo.low_stock_threshold
FROM branches branch
CROSS JOIN branch_inventory demo
WHERE branch.id::text LIKE '11000000-%'
  AND demo.branch_id='10000000-0000-0000-0000-000000000001'
ON CONFLICT (branch_id, product_id) DO UPDATE SET
on_hand=EXCLUDED.on_hand, reserved=0, low_stock_threshold=EXCLUDED.low_stock_threshold,
version=branch_inventory.version+1, updated_at=now();
